DO $$
DECLARE
  v_cables bigint; v_lps bigint; v_ips bigint;
BEGIN
  SELECT COUNT(*) INTO v_cables FROM cables;
  SELECT COUNT(*) INTO v_lps    FROM landing_points;
  SELECT COUNT(*) INTO v_ips    FROM endpoint_ip_samples;
